CREATE OR REPLACE FUNCTION "order_enqueue_orderShipments"() RETURNS trigger AS $$
BEGIN
  -- Enqueues a message of OrderShipped after a write to order (D80).
  IF TG_OP = 'UPDATE' AND NOT (OLD.note IS DISTINCT FROM NEW.note) THEN
    RETURN NULL;
  END IF;
  INSERT INTO "orderShipments" ("orderId", note) VALUES (NEW.id, NEW.note)
    ON CONFLICT ("orderId") WHERE state = 'ready' DO UPDATE SET note = excluded.note, due_at = excluded.due_at, attempts = 0, last_error = NULL, updated_at = now();
  RETURN NULL;
END;
$$ LANGUAGE plpgsql
